# OSM test account credentials
# Account should be registered but NOT require email verification
TEST_OSM_USERNAME=fmc_1
TEST_OSM_PASSWORD=@2&Ro9VB56dQH7^LH3aC

# Playwright-only secrets live here; Vitest does not load this file.
# `VITE_*` for the app live in the repo root `.env`.

# VITE_PLAYWRIGHT_ENABLED: set in repo root `.env` (see `.env.example`).
# This enables Playwright testing mode (test IDs and mapLoaded event) for E2E testing

